CREATE TYPE public.app_role AS ENUM ('superadmin','admin','user');
CREATE TABLE public.user_roles (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL DEFAULT 'user', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY roles_own ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.account_access (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'pendente' CHECK(status IN ('pendente','ativo','suspenso')), terms_version text, terms_accepted_at timestamptz, last_access_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.account_access TO authenticated; GRANT ALL ON public.account_access TO service_role;
ALTER TABLE public.account_access ENABLE ROW LEVEL SECURITY;
CREATE POLICY access_own ON public.account_access FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.admin_settings (id boolean PRIMARY KEY DEFAULT true CHECK(id), manual_approval boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.admin_settings TO service_role;
ALTER TABLE public.admin_settings ENABLE ROW LEVEL SECURITY;
INSERT INTO public.admin_settings(id) VALUES(true);
CREATE TABLE public.audit_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid NOT NULL, target_id uuid, action text NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.audit_log TO service_role;
ALTER TABLE public.audit_log ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.has_role(uid uuid, role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=uid AND r.role=$2) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.account_active() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.account_access WHERE user_id=auth.uid() AND status='ativo' AND terms_accepted_at IS NOT NULL) $$;
REVOKE ALL ON FUNCTION public.account_active() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.account_active() TO authenticated,service_role;
INSERT INTO public.user_roles(user_id,role) SELECT id, CASE WHEN lower(email)='vinicius@crmcontent.com' THEN 'superadmin'::public.app_role WHEN papel='admin' THEN 'admin'::public.app_role ELSE 'user'::public.app_role END FROM public.profiles;
INSERT INTO public.account_access(user_id,status,terms_version,terms_accepted_at) SELECT id,'ativo','legacy',now() FROM public.profiles;
CREATE OR REPLACE FUNCTION public.ao_criar_usuario() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
INSERT INTO public.profiles(id,nome,email) VALUES(new.id,coalesce(new.raw_user_meta_data->>'full_name',split_part(new.email,'@',1)),new.email) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.memoria(user_id) VALUES(new.id) ON CONFLICT(user_id) DO NOTHING;
INSERT INTO public.user_roles(user_id,role) VALUES(new.id,'user') ON CONFLICT(user_id) DO NOTHING;
INSERT INTO public.account_access(user_id,status) SELECT new.id,CASE WHEN manual_approval THEN 'pendente' ELSE 'ativo' END FROM public.admin_settings WHERE id=true ON CONFLICT(user_id) DO NOTHING;
RETURN new; END $$;
CREATE OR REPLACE FUNCTION public.meu_papel() RETURNS public.papel_usuario LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role IN ('admin','superadmin')) THEN 'admin'::public.papel_usuario ELSE 'cs'::public.papel_usuario END $$;
CREATE OR REPLACE FUNCTION public.gerenciar_perfil() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF current_user IN ('authenticated','anon') AND (new.papel IS DISTINCT FROM old.papel OR new.email IS DISTINCT FROM old.email OR new.id IS DISTINCT FROM old.id OR new.pipedrive_user_id IS DISTINCT FROM old.pipedrive_user_id) THEN RAISE EXCEPTION 'Campos protegidos'; END IF; RETURN new; END $$;
DROP POLICY profiles_select ON public.profiles; DROP POLICY profiles_admin_all ON public.profiles;
CREATE POLICY profiles_select ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid());
DROP POLICY uso_admin_all ON public.uso;
DROP POLICY config_select_own ON public.config_usuario;
CREATE POLICY config_select_own ON public.config_usuario FOR SELECT TO authenticated USING(user_id=auth.uid());
DROP POLICY convites_admin_all ON public.convites;
CREATE POLICY convites_admin_all ON public.convites FOR ALL TO authenticated USING(public.has_role(auth.uid(),'superadmin') OR public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'superadmin') OR public.has_role(auth.uid(),'admin'));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['mensagens','memoria','notas','acoes','briefings','uso','config_usuario'] LOOP EXECUTE format('CREATE POLICY active_required ON public.%I AS RESTRICTIVE FOR ALL TO authenticated USING(public.account_active()) WITH CHECK(public.account_active())',t); END LOOP; END $$;
CREATE TRIGGER user_roles_updated BEFORE UPDATE ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.tocar_atualizado_em();
CREATE TRIGGER account_access_updated BEFORE UPDATE ON public.account_access FOR EACH ROW EXECUTE FUNCTION public.tocar_atualizado_em();
CREATE TRIGGER admin_settings_updated BEFORE UPDATE ON public.admin_settings FOR EACH ROW EXECUTE FUNCTION public.tocar_atualizado_em();
CREATE TRIGGER audit_log_updated BEFORE UPDATE ON public.audit_log FOR EACH ROW EXECUTE FUNCTION public.tocar_atualizado_em();